const glb1 = readGlb(buf1);
const s = glb1.byName.get("STARTG1TILES")[0];
const e = glb1.byName.get("ENDG1TILES")[0];
console.log("STARTG1TILES index", s, "ENDG1TILES index", e, "=> tiles", s + 1, "to", e - 1, "count", e - s - 1);
const sizes = new Map();
for (let i = s + 1; i < e; i++) {
  const raw = getItemIndex(glb1, i);
  sizes.set(raw.length, (sizes.get(raw.length) || 0) + 1);
}
console.log("size histogram:", [...sizes.entries()]);
// show a few tile headers
for (let i = s + 1; i < s + 4; i++) {
  const raw = getItemIndex(glb1, i);
  const hdr = new DataView(raw.buffer, raw.byteOffset, 20);
  console.log("tile", i, "hdr:", hdr.getInt32(0, true), hdr.getInt32(4, true), hdr.getInt32(8, true), hdr.getInt32(12, true), hdr.getInt32(16, true), "len", raw.length);
}

